import '../styles/main.css';
import { Marked } from 'marked';
import DOMPurify from 'dompurify';
import Toolbar from './toolbar/Toolbar.js';
import Tool from './toolbar/Tool.js';
import { modal } from './modal.js';
import Preview from './Preview.js';
import Footer from './Footer.js';
import UndoRedoManager from '../utils/UndoRedoManager.js';
import IndentManager from '../utils/IndentManager.js';
import ListManager from '../utils/ListManager.js';
import ShortcutManager from '../utils/ShortcutManager.js';
import FindReplace from '../utils/FindReplace.js';
import PasteManager from '../utils/PasteManager.js';
import { applyVariableSamples } from '../utils/variables.js';

// Own instance rather than marked.setOptions(), which would mutate the shared
// singleton and silently change behaviour for a host app that also uses marked.
const defaultRenderer = new Marked({ breaks: true });

class MarkdownEditor {
    constructor(selector, options = {}) {
        this.usertextarea = typeof selector === 'string' ? document.querySelector(selector) : selector;
        this.options = options;
        this.mode = options.mode || 'plain';
        this.preview = (this.options.toolbar) ? this.options.toolbar.includes('preview') : true;
        this.footerOptions = this._parseFooterOptions(options.footer);
        this.variables = this._parseVariables(options.toolbar);
        this.imageUpload = this._parseImageUpload(options.toolbar);
        this.previewTimer = null;
        this.init();
        this.undoRedoManager = new UndoRedoManager(this);
        this.listManager = new ListManager(this);
        this.indentManager = new IndentManager(this);
        this.shortcutManager = new ShortcutManager(this);
        this.findReplace = new FindReplace(this);
        this.pasteManager = new PasteManager(this);
    }

    /**
     * Returns the translation for a UI string, or the string itself when none is
     * configured. Keyed by the English text, the way gettext is, so a tool does
     * not need to know anything about translation.
     */
    label(text) {
        return this.options.labels?.[text] ?? text;
    }

    /**
     * Upload settings live in the toolbar as { image: { fileInput: {...} } }, but
     * paste and drop need them before the toolbar exists. Read them up front, and
     * only when an upload endpoint is actually configured.
     */
    _parseImageUpload(toolbar) {
        const entry = (Array.isArray(toolbar) ? toolbar : [])
            .find(tool => tool && typeof tool === 'object' && tool.image);
        const fileInput = entry?.image?.fileInput;
        return fileInput?.uploadUrl ? fileInput : null;
    }

    /**
     * Variables are configured inline in the toolbar as { variables: [...] },
     * but the preview needs them before the toolbar exists, since createEditor()
     * renders first. Read them from the toolbar array at construction instead.
     */
    _parseVariables(toolbar) {
        const entry = (Array.isArray(toolbar) ? toolbar : [])
            .find(tool => tool && typeof tool === 'object' && Array.isArray(tool.variables));
        return entry ? entry.variables : [];
    }

    _parseFooterOptions(footer) {
        if (footer === false) return null;
        const opts = footer ?? {};
        return {
            line:  opts.line  !== false,
            col:   opts.col   !== false,
            chars: opts.chars !== false,
            words: opts.words === true,
        };
    }

    init() {
        this.createEditor();
        this.addToolbar();
        this.addFooter();
        this._toolbarH = this.editorContainer.querySelector('.toolbar')?.offsetHeight ?? 0;
        this._footerH = this.editorContainer.querySelector('.editor-footer')?.offsetHeight ?? 0;
        this._autoGrow();
    }

    createEditor() {
        if (!this.isTextareaValid()) return;

        this.applyDefaultAttributes();
        this.buildEditorLayout();
        this.addInputListener();
        this.render();
    }

    isTextareaValid() {
        return this.usertextarea.tagName === 'TEXTAREA';
    }

    applyDefaultAttributes() {
        const hasLabel = (this.usertextarea.id && document.querySelector(`label[for="${this.usertextarea.id}"]`))
            || this.usertextarea.getAttribute('aria-label')
            || this.usertextarea.getAttribute('aria-labelledby');
        if (!hasLabel) {
            this.usertextarea.setAttribute('aria-label', this.options.label || 'Markdown editor');
            this._addedAriaLabel = true;
        }

        this.usertextarea.classList.add(
            "editor-textarea",
            "fj:focus:ring-0",
            "fj:focus:outline-0",
            "fj:border-0",
            "fj:border-base-soft",
            "fj:px-4",
            "fj:py-2",
            "fj:max-w-full",
            "fj:w-full",
            "fj:h-full",
            "fj:bg-transparent",
            "fj:outline-0",
            "fj:appearance-none",
            "fj:overflow-y-auto",
            // The wrapper is the resizable element. Without this the textarea
            // keeps the browser's own grip, so plain mode showed two handles
            // and dragging the inner one sized the textarea out of its box.
            // Hybrid mode set it already, which is why only plain mode showed it.
            "fj:resize-none",
        );
        if (!this.usertextarea.hasAttribute('placeholder')) {
            this.usertextarea.placeholder = this.options.placeholder || 'Write your markdown...';
        }
    }

    buildEditorLayout() {
        this.editorContainer = document.createElement('div');
        this.editorContainer.className = `
            markdown-editor-wrapper
            fj:me-surface
            fj:me-surface-outline
            fj:me-surface-rounded
            fj:overflow-hidden
            fj:flex
            fj:flex-col
        `;
        const theme = this.options.theme
            ?? this.usertextarea.closest('[data-theme]')?.getAttribute('data-theme');
        if (theme) this.editorContainer.setAttribute('data-theme', theme);

        // Mirror the textarea's id so a single editor can be targeted in CSS.
        // Copied as a data attribute, not an id, so getElementById still
        // resolves to the textarea.
        if (this.usertextarea.id) this.editorContainer.dataset.editor = this.usertextarea.id;

        this.editorContainer.style.minHeight = (this.options.minHeight ?? 200) + 'px';

        this.usertextarea.parentNode.insertBefore(this.editorContainer, this.usertextarea);

        this.markdownEditorDiv = document.createElement('div');
        this.markdownEditorDiv.className = `editor-layout fj:relative fj:grid fj:grid-cols-1 fj:flex-1 fj:min-h-0`;
        this.editorContainer.appendChild(this.markdownEditorDiv);

        this.addTextareaWrapper();
        if (this.preview) this.addPreviewWrapper();
    }

    addTextareaWrapper() {
        const textareaContainer = document.createElement('div');
        textareaContainer.className = `
            textarea-wrapper
            not-prose
            fj:me-surface
            fj:h-full
            fj:min-h-0
            fj:relative
            fj:grid
        `;

        if(this.mode == 'hybrid'){
            this.displayLayer = document.createElement('div');
            this.displayLayer.setAttribute('data-placeholder', this.usertextarea.placeholder);
            this.displayLayer.setAttribute("aria-hidden", true);
            this.displayLayer.className = `
                display-layer
                fj:px-4
                fj:py-2
                fj:whitespace-pre-wrap fj:wrap-break-word
                fj:pointer-events-none
                fj:absolute
                fj:inset-0
                fj:m-0
                fj:box-border
                fj:z-0
                fj:overflow-y-auto
                fj:empty:after:content-[attr(data-placeholder)]
                fj:empty:after:absolute
                fj:empty:after:inset-0
                fj:empty:after:px-4
                fj:empty:after:py-2
                fj:empty:after:text-[CanvasText]
                fj:empty:after:opacity-50
            `;

            this.usertextarea.className += `
                fj:text-transparent
                fj:caret-primary
                fj:outline-none
                fj:m-0
                fj:box-border
                fj:relative
                fj:z-10
            `;

            textareaContainer.appendChild(this.displayLayer);
        }

        textareaContainer.appendChild(this.usertextarea);
        this.markdownEditorDiv.appendChild(textareaContainer);
    }

    

    addPreviewWrapper() {
        const previewInstance = new Preview(this.markdownEditorDiv);
        this.previewContent = previewInstance.getPreviewContent();
    }

    addInputListener() {
        this._inputHandler = () => {
            this._autoGrow();
            this.renderHybrid(); // Fast: Only Regex
            this.debouncedPreview(); // Slow: Heavy Markdown Parse
            this.notifyChange();
        };

        this._scrollHandler = () => {
            if (this._scrollRaf) return;
            this._scrollRaf = requestAnimationFrame(() => {
                this._scrollRaf = null;

                if (this.mode === 'hybrid') {
                    // PIXEL PERFECT SYNC: Do not use ratios for the hybrid layer
                    this.displayLayer.scrollTop = this.usertextarea.scrollTop;
                    this.displayLayer.scrollLeft = this.usertextarea.scrollLeft;
                }

                if (this.preview && this.previewContent) {
                    // RATIO SYNC: Use ratio only for the fully rendered preview
                    this._syncPreviewScroll();
                }
            });
        };

        this.usertextarea.addEventListener('input', this._inputHandler);
        this.usertextarea.addEventListener('scroll', this._scrollHandler);
    }

    debouncedPreview() {
        if (!this.preview) return;
        clearTimeout(this.previewTimer);
        this.previewTimer = setTimeout(() => {
            // Replacing the markup resets the preview to the top, so remember
            // where the reader was in case the textarea cannot drive it.
            const keep = this.previewContent.scrollTop;
            this.previewContent.innerHTML = this._renderMarkdown(this.usertextarea.value);
            this.wirePreviewCheckboxes();
            if (!this._syncPreviewScroll()) this.previewContent.scrollTop = keep;
        }, 150); // 150ms delay feels instant but saves CPU
    }

    /**
     * Keeps the preview at the same proportion of the way down as the textarea.
     *
     * Only when the textarea can actually scroll. If it cannot, the range is
     * zero, and the old code divided by it: 0/0 is NaN, the browser stores that
     * as 0, and the preview jumped to the top. Source that renders taller than
     * it reads, a handful of images say, hits this on every keystroke, pulling
     * the reader back to the start of a preview they were scrolled into.
     *
     * Returns whether it set a position, so the caller knows if it has to put
     * the reader back itself.
     */
    _syncPreviewScroll() {
        if (!this.preview || !this.previewContent) return false;

        const textarea = this.usertextarea;
        const range = textarea.scrollHeight - textarea.clientHeight;
        if (range <= 0) return false;

        const ratio = textarea.scrollTop / range;
        const previewRange = this.previewContent.scrollHeight - this.previewContent.clientHeight;
        this.previewContent.scrollTop = ratio * previewRange;
        return true;
    }

    /**
     * Renders markdown to sanitized HTML exactly as the preview does, honouring
     * the configured renderer and sanitizer. Useful from a custom tool that has
     * to embed rendered content, such as a tooltip body.
     */
    renderMarkdown(markdown) {
        return this._renderMarkdown(markdown);
    }

    /**
     * Builds a small toolbar bound to another textarea, for a custom tool that
     * collects rich text in its own dialog. The tools are the real ones, so they
     * behave identically, and this replaces hand-rolling a fake editor object.
     *
     * Returns the toolbar element; append it wherever you like.
     */
    createToolbar(textarea, tools = ['bold', 'italic', 'strikethrough']) {
        const host = Object.create(this);

        // Only the target and the write path differ. Everything else, including
        // label() and the options, is inherited from the real editor.
        host.usertextarea = textarea;
        host.render = () => {};
        host.notifyChange = () => {};
        host.insertText = (text, selectionOffset = 0, trailingLength = 0) => {
            const { selectionStart, selectionEnd, value } = textarea;
            const scrollTop = textarea.scrollTop;
            textarea.value = value.slice(0, selectionStart) + text + value.slice(selectionEnd);
            textarea.focus();
            textarea.setSelectionRange(
                selectionStart + selectionOffset,
                selectionStart + text.length - trailingLength,
            );
            textarea.scrollTop = scrollTop;
        };

        return new Toolbar(host, tools, { standalone: true }).toolbar;
    }

    _renderMarkdown(markdown) {
        const render   = this.options.renderer  ?? (md   => defaultRenderer.parse(md));
        const sanitize = this.options.sanitizer ?? (html => DOMPurify.sanitize(html));

        // Variables that declare a sample are shown as that sample in the preview.
        // Only this copy is affected; the textarea keeps the real placeholders.
        const source = applyVariableSamples(markdown, this.variables);
        const html = render(source);

        // Clickable checkboxes are matched by index against task-list lines, so a
        // custom renderer that emits none breaks them silently. Warn once.
        if (this.options.renderer && !this._taskListWarned
            && /^\s*[-*] \[[ xX]\] /m.test(source) && !/type=["']?checkbox/.test(html)) {
            this._taskListWarned = true;
            console.warn('[MarkdownEditor] Task list syntax found, but the custom renderer emitted no checkboxes. Clickable checkboxes in the preview need a task-list plugin, e.g. markdown-it-task-lists.');
        }

        return sanitize(html);
    }

    wirePreviewCheckboxes() {
        const checkboxes = this.previewContent.querySelectorAll('input[type="checkbox"]');
        checkboxes.forEach((checkbox, index) => {
            checkbox.removeAttribute('disabled');
            checkbox.addEventListener('click', (e) => {
                e.preventDefault();
                const lines = this.usertextarea.value.split('\n');
                let count = 0;
                for (let i = 0; i < lines.length; i++) {
                    if (/^(\s*)([-*] \[[ xX]\] )/.test(lines[i])) {
                        if (count === index) {
                            if (checkbox.checked) {
                                lines[i] = lines[i].replace(/\[ \]/, '[x]');
                            } else {
                                lines[i] = lines[i].replace(/\[[xX]\]/, '[ ]');
                            }
                            break;
                        }
                        count++;
                    }
                }
                this.usertextarea.value = lines.join('\n');
                this.render();
                this.notifyChange();
            });
        });
    }

    addFooter() {
        if (!this.footerOptions) return;
        const { line, col, chars, words } = this.footerOptions;
        if (!line && !col && !chars && !words) return;
        this.footer = new Footer(this.editorContainer, this.footerOptions);
        this.footer.update(this.usertextarea);

        this._footerUpdate = () => this.footer.update(this.usertextarea);
        this.usertextarea.addEventListener('input', this._footerUpdate);
        this.usertextarea.addEventListener('click', this._footerUpdate);
        this.usertextarea.addEventListener('keyup', this._footerUpdate);
        this.usertextarea.addEventListener('focus', this._footerUpdate);
    }

    addToolbar() {
        this.toolbarInstance = new Toolbar(
            this,
            this.options.toolbar ||
            [
                // History/System (Usually far left)
                'undo', 
                'redo',
                
                // Block Structure
                'heading', 
                'blockquote', 
                
                // Lists & Indentation
                'ul', 
                'ol', 
                'checklist', 
                'outdent', 
                'indent', 
                
                // Inline Formatting
                'bold',
                'italic',
                'strikethrough',
                'code',

                // Block Formatting
                'codeblock',
                'hr',
                'table',

                // Rich Media/Links
                'link',
                'image',
                
                // View/Preview (Usually far right)
                'preview'
            ]
        );
    }

    insertText(text, selectionOffset = 0, trailingLength = 0) {
        const { selectionStart, selectionEnd } = this.usertextarea;
        const value = this.usertextarea.value;
        const scrollTop = this.usertextarea.scrollTop;

        this.usertextarea.value = `${value.substring(0, selectionStart)}${text}${value.substring(selectionEnd)}`;
        this.usertextarea.focus();
        this.usertextarea.setSelectionRange(selectionStart + selectionOffset, selectionStart + text.length - trailingLength);

        this.render();
        this.notifyChange();
        this.restoreScroll(scrollTop);
    }

    /**
     * Puts the reader back where they were after an edit. Assigning `value`
     * resets the textarea to the top, so without this, formatting a word near
     * the end of a long document threw you back to the first line (#46).
     *
     * Call it after render(), because _autoGrow() changes the height and so the
     * range scrollTop is clamped to.
     */
    restoreScroll(scrollTop) {
        this.usertextarea.scrollTop = scrollTop;
    }

    /**
     * Kept so a custom tool calling it still works, but it no longer moves the
     * view. It used to derive a scroll position from `line-height`, which
     * computes to `normal` unless a page sets it, so parseInt gave NaN and the
     * textarea jumped to the top on every edit. Counting '\n' also ignored
     * wrapped lines, so even with a real line-height the position was short.
     * Holding the existing scroll is both correct and cheaper: an edit at the
     * caret leaves the caret where the reader was already looking.
     */
    scrollToView() {}


    _highlight(rawValue) {
        let out = rawValue
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;');

        out = out
            .replace(/```(\w+)?\n([\s\S]*?)```/g,
                '<span class="fj:opacity-30">```$1</span>\n$2<span class="fj:opacity-30">```</span>')
            .replace(/`([^`\n]+)`/g,
                '<span class="fj:opacity-40">`</span><span class="fj:text-accent">$1</span><span class="fj:opacity-40">`</span>')
            .replace(/^(#+ )(.*)$/gm,
                '<span class="fj:text-primary"><span class="fj:opacity-40">$1</span><span class="faux-bold">$2</span></span>')
            .replace(/\*\*(.*?)\*\*/g,
                '<span class="fj:text-secondary"><span class="fj:opacity-40">**</span><span class="faux-bold">$1</span><span class="fj:opacity-40">**</span></span>')
            .replace(/^([\s]*)([\-\*] |[\d]+\. |\[[\s xX]\] )(.*)$/gm,
                '$1<span class="fj:text-primary">$2</span>$3')
            .replace(/(\*|_)(.*?)\1/g,
                '<span class="fj:text-accent"><span class="fj:opacity-40">$1</span>$2<span class="fj:opacity-40">$1</span></span>')
            .replace(/~~(.*?)~~/g,
                '<span class="fj:line-through fj:opacity-70"><span class="fj:opacity-40">~~</span>$1<span class="fj:opacity-40">~~</span></span>')
            .replace(/(?<!~)(~)([^~]+)\1(?!~)/g,
                '<span class="fj:line-through fj:opacity-70"><span class="fj:opacity-40">$1</span>$2<span class="fj:opacity-40">$1</span></span>')
            .replace(/(!?\[)(.*?)(\]\()(.*?)(\))/g,
                '<span class="fj:opacity-40">$1</span><span class="fj:text-primary">$2</span><span class="fj:opacity-40">$3</span><span class="fj:underline fj:opacity-50">$4</span><span class="fj:opacity-50">$5</span>');

        if (rawValue.endsWith('\n')) out += ' ';
        return out;
    }

    renderHybrid() {
        if (this.mode !== 'hybrid') return;

        const rawValue = this.usertextarea.value;
        if (rawValue === this._lastRaw) return;
        this._lastRaw = rawValue;

        const highlighted = this._highlight(rawValue);
        const newLines = highlighted.split('\n');
        const lastLines = this._lastLines;

        if (!lastLines || lastLines.length !== newLines.length) {
            this.displayLayer.innerHTML = '';
            this._lineNodes = newLines.map((line, i) => {
                const node = document.createElement('span');
                node.innerHTML = line + (i < newLines.length - 1 ? '\n' : '');
                this.displayLayer.appendChild(node);
                return node;
            });
            this._lastLines = newLines.slice();
            return;
        }

        for (let i = 0; i < newLines.length; i++) {
            if (newLines[i] !== lastLines[i]) {
                this._lineNodes[i].innerHTML = newLines[i] + (i < newLines.length - 1 ? '\n' : '');
                lastLines[i] = newLines[i];
            }
        }
    }

    _autoGrow() {
        if (this.editorContainer.classList.contains('is-fullscreen')) return;

        // The wrapper is resizable, and dragging it writes an inline height.
        // Once that differs from the height we last set, the reader has chosen
        // one themselves, so stop overwriting it on every keystroke (#46).
        if (this._autoHeight !== undefined
            && this.editorContainer.style.height !== this._autoHeight) {
            this._userResized = true;
        }
        if (this._userResized) return;

        const textarea = this.usertextarea;
        // Shrink to 1px to measure natural content height (bypasses h-full)
        textarea.style.height = '1px';
        const contentHeight = textarea.scrollHeight;
        textarea.style.height = ''; // restore — h-full class takes over

        const maxHeight = this.options.maxHeight ?? 500;
        const height = Math.min(contentHeight, maxHeight) + this._toolbarH + this._footerH + 1;

        // The first call comes from the constructor, before the toolbar and
        // footer have been measured, so this is NaN. Leave _autoHeight unset
        // rather than recording a height the browser will refuse: a mismatch
        // on the next call would read as the reader having resized it, and
        // auto-grow would switch itself off for good.
        if (!Number.isFinite(height)) return;

        this._autoHeight = height + 'px';
        this.editorContainer.style.height = this._autoHeight;
    }

    notifyChange() {
        if (this.options.onChange) this.options.onChange(this.usertextarea.value);
    }

    render() {
        this._autoGrow();
        this.renderHybrid();
        if (this.preview) {
            this.previewContent.innerHTML = this._renderMarkdown(this.usertextarea.value);
            this.wirePreviewCheckboxes();
        }
    }

    destroy() {
        this.shortcutManager?.destroy();
        this.findReplace?.destroy();
        this.previewTool?.destroy();
        this.undoRedoManager?.destroy();
        this.listManager?.destroy();
        this.pasteManager?.destroy();
        // Reaches toolbar tools, including custom ones that added listeners
        this.toolbarInstance?.destroy();

        if (this._footerUpdate) {
            this.usertextarea.removeEventListener('input', this._footerUpdate);
            this.usertextarea.removeEventListener('click', this._footerUpdate);
            this.usertextarea.removeEventListener('keyup', this._footerUpdate);
            this.usertextarea.removeEventListener('focus', this._footerUpdate);
        }

        this.usertextarea.removeEventListener('input', this._inputHandler);
        this.usertextarea.removeEventListener('scroll', this._scrollHandler);

        const parent = this.editorContainer.parentNode;
        if (!parent) return;

        // Strip classes added by applyDefaultAttributes
        const addedClasses = [
            'editor-textarea', 'fj:focus:ring-0', 'fj:focus:outline-0', 'fj:border-0',
            'fj:border-base-soft', 'fj:px-4', 'fj:py-2', 'fj:max-w-full', 'fj:w-full',
            'fj:h-full', 'fj:bg-transparent', 'fj:outline-0', 'fj:appearance-none', 'fj:overflow-y-auto',
            'fj:text-transparent', 'fj:caret-primary', 'fj:resize-none', 'fj:outline-none',
            'fj:m-0', 'fj:box-border', 'fj:relative', 'fj:z-10',
        ];
        addedClasses.forEach(cls => this.usertextarea.classList.remove(cls));

        if (this._addedAriaLabel) this.usertextarea.removeAttribute('aria-label');
        this.usertextarea.style.height = '';

        parent.insertBefore(this.usertextarea, this.editorContainer);
        this.editorContainer.remove();
    }
}

// Exposed so you can write your own toolbar tool without forking. Attached to
// the class rather than exported by name, because adding a named export would
// change the shape of the UMD and IIFE globals and break every <script> user.
MarkdownEditor.Tool = Tool;
MarkdownEditor.modal = modal;

export default MarkdownEditor;